mapper.select:
SELECT TEMP.*, (select v.MEANING from sys_code_value_b_v v where v.code = 'PLM.FC_RESULT' AND v.code_value = temp.suggested_classification)suggested_classification_n, (select v.MEANING from sys_code_value_b_v v where v.code = 'PLM.FC_RESULT' AND v.code_value = temp.final_classification_result)final_classification_result_n FROM ( SELECT pfcc.five_classify_con_id, pfcc.five_classification_id, pfcc.contract_id, pfcc.contract_type, pfcc.contract_prj_name, pfcc.last_classification_result, pfcc.first_classification_time, pfcc.first_classification_result, pfcc.final_classification_time, pfcc.final_classification_result, pfcc.is_inter_manage_abnormal, pfcc.is_production_line_stopped, pfcc.is_product_structure_change, pfcc.is_market_price_leasing, pfcc.is_other_cases, pfcc.is_major_plan, pfcc.is_executive_personnel_change, pfcc.is_external_environment, pfcc.is_major_proceedings, pfcc.is_major_penalty, pfcc.is_major_accidents, pfcc.is_major_other_cases, pfcc.is_value_reduced, pfcc.guarantor_financial_status, pfcc.other_guarantees_situation, pfcc.operating_profit_status, pfcc.revenue_comparison_status, pfcc.oper_cf_change_status, pfcc.net_operating_cashflow_status, pfcc.other_financial_situation, pfcc.lease_rent_situation, pfcc.other_inst_overdue_situation, pfcc.two_years_losses_status, pfcc.credit_formula_system_status, pfcc.other_cases_situation, pfcc.change_iq, pfcc.change_time, pfcc.approval_node, pfcc.classification_reason, con.project_id, con.approval_number, con.contract_name, con.contract_number, con.contract_status, con.business_type, hbm.bp_name contract_bp_name, pro_bp.bp_name warrant_bp_name, hbm.internal_indu, cash.contract_amount, fou.unit_name contract_business_department, cash.contract_remaining_principal, cash.contract_remaining_amount, cash.fine_days, CASE WHEN cash.fine_days <=30 THEN 'NORMAL' WHEN cash.fine_days <=180 THEN 'ATTENTION' WHEN cash.fine_days <=365 THEN 'SECONDARY' WHEN cash.fine_days <=730 THEN 'SUSPICIOUS' ELSE 'LOSS' END suggested_classification FROM plm_five_classify_con pfcc JOIN fct_contract con ON con.contract_id=pfcc.contract_id AND pfcc.contract_type='FCT' JOIN ( SELECT fqc.contract_id, nvl(MAX(fqc.fine_days),0) fine_days, SUM((case when fqc.cf_item = 0 then nvl(fqc.received_amount,0) else 0 end)) contract_amount, SUM( CASE WHEN fqc.cf_item=54 THEN fqc.due_amount-nvl(fqc.received_amount,0) ELSE 0 END )contract_remaining_principal, SUM( CASE WHEN fqc.cf_item=54 or fqc.cf_item=55 THEN fqc.due_amount-nvl(fqc.received_amount,0) ELSE 0 END ) contract_remaining_amount FROM fct_quotation_cashflow fqc GROUP BY fqc.contract_id) cash ON cash.contract_id=con.contract_id JOIN fct_project_bp fpb ON fpb.project_id= con.project_id AND fpb.credit_grantor_party='Y' JOIN hls_bp_master hbm ON hbm.bp_id=fpb.bp_id JOIN fnd_org_unit fou ON fou.unit_id=con.unit_id LEFT JOIN ( SELECT pb.project_id, wm_concat(bm.bp_name) bp_name FROM fct_project_bp pb, hls_bp_master bm WHERE bm.bp_id=pb.bp_id AND pb.bp_role_type NOT IN('BUYER', 'SELLER') GROUP BY pb.project_id) pro_bp ON pro_bp.project_id= con.project_id
UNION
SELECT pfcc.five_classify_con_id, pfcc.five_classification_id, pfcc.contract_id, pfcc.contract_type, pfcc.contract_prj_name, pfcc.last_classification_result, pfcc.first_classification_time, pfcc.first_classification_result, pfcc.final_classification_time, pfcc.final_classification_result, pfcc.is_inter_manage_abnormal, pfcc.is_production_line_stopped, pfcc.is_product_structure_change, pfcc.is_market_price_leasing, pfcc.is_other_cases, pfcc.is_major_plan, pfcc.is_executive_personnel_change, pfcc.is_external_environment, pfcc.is_major_proceedings, pfcc.is_major_penalty, pfcc.is_major_accidents, pfcc.is_major_other_cases, pfcc.is_value_reduced, pfcc.guarantor_financial_status, pfcc.other_guarantees_situation, pfcc.operating_profit_status, pfcc.revenue_comparison_status, pfcc.oper_cf_change_status, pfcc.net_operating_cashflow_status, pfcc.other_financial_situation, pfcc.lease_rent_situation, pfcc.other_inst_overdue_situation, pfcc.two_years_losses_status, pfcc.credit_formula_system_status, pfcc.other_cases_situation, pfcc.change_iq, pfcc.change_time, pfcc.approval_node, pfcc.classification_reason, fp.project_id, fp.approval_number, con.contract_name, con.contract_number, con.contract_status, con.business_type, hbm.bp_name contract_bp_name, pro_bp.bp_name warrant_bp_name, hbm.internal_indu, cash.contract_amount, fou.unit_name contract_business_department, cash.contract_remaining_principal, cash.contract_remaining_amount, cash.fine_days, CASE WHEN cash.fine_days <=30 THEN 'NORMAL' WHEN cash.fine_days <=180 THEN 'ATTENTION' WHEN cash.fine_days <=365 THEN 'SECONDARY' WHEN cash.fine_days <=730 THEN 'SUSPICIOUS' ELSE 'LOSS' END suggested_classification FROM plm_five_classify_con pfcc JOIN con_contract con ON con.contract_id=pfcc.contract_id AND pfcc.contract_type='CON' JOIN ( SELECT ccc.contract_id, SUM((case when ccc.cf_item = 0 then nvl(ccc.received_amount,0) else 0 end)) contract_amount, nvl(MAX(ccc.fine_days),0) fine_days, SUM( CASE WHEN ccc.cf_item=1 THEN ccc.principal-nvl(ccc.received_principal,0) ELSE 0 END ) contract_remaining_principal, SUM( CASE WHEN ccc.cf_item=1 THEN ccc.due_amount-nvl(ccc.received_amount,0) ELSE 0 END ) contract_remaining_amount FROM con_contract_cashflow ccc GROUP BY ccc.contract_id) cash ON cash.contract_id=con.contract_id JOIN prj_project fp ON fp.project_id= con.project_id JOIN hls_bp_master hbm ON hbm.bp_id=con.tenant_id JOIN fnd_org_unit fou ON fou.unit_id=con.unit_id LEFT JOIN ( SELECT pb.project_id, wm_concat(bm.bp_name) bp_name FROM prj_project_bp pb, hls_bp_master bm WHERE bm.bp_id=pb.bp_id AND pb.bp_type NOT IN('TENANT', 'TENANT_SEC') AND pb.bp_categroy='PRJ_PROJECT' GROUP BY pb.project_id) pro_bp ON pro_bp.project_id= con.project_id ) TEMP WHERE 1=1
AND TEMP.five_classification_id = #{fiveClassificationId}
AND TEMP.contract_number IN
#{item}

SELECT DISTINCT pfcc.* FROM plm_five_classify_con pfcc, con_contract cc, fnd_employee_assigns fea, sys_user_allocation sua, fnd_employee fe, prj_project prj, act_assignee_node aan
fea.employee_assign_id = sua.employee_assign_id AND fe.employee_id = fea.employee_id AND prj.project_id = cc.project_id AND prj.ref_project_id = aan.project_id AND aan.assignee_code = fe.employee_code AND pfcc.contract_id = cc.contract_id AND aan.assignee_type = 'RISK' AND aan.project_document_category = 'PRJ_PROJECT'
AND fea.company_id = #{companyId} AND sua.company_id = #{companyId} AND sua.user_id = #{userId} AND pfcc.contract_type = 'CON'
AND pfcc.five_classification_id = #{fiveClassificationId}
AND pfcc.change_iq = #{changeIq}
AND pfcc.contract_id IN
#{item}
AND pfcc.approval_node = #{approvalNode}
order by pfcc.contract_number desc

SELECT DISTINCT pfcc.* FROM plm_five_classify_con pfcc, fct_contract fct, fnd_employee_assigns fea, sys_user_allocation sua, fnd_employee fe, fct_project fpj, act_assignee_node aan
fea.employee_assign_id = sua.employee_assign_id AND fe.employee_id = fea.employee_id AND fpj.project_id = fct.project_id AND fpj.ref_project_id = aan.project_id AND aan.assignee_code = fe.employee_code AND aan.assignee_type = 'RISK' AND aan.project_document_category = 'FCT_PROJECT' AND pfcc.contract_id = fct.contract_id AND fea.company_id = #{companyId} AND sua.company_id = #{companyId} AND sua.user_id = #{userId} AND pfcc.contract_type = 'FCT'
AND pfcc.five_classification_id = #{fiveClassificationId}
AND pfcc.change_iq = #{changeIq}
AND pfcc.contract_id IN
#{item}
AND pfcc.approval_node = #{approvalNode}

SELECT pfcc.*,pfc.five_classification_type, nvl(( SELECT rp.reserve_plan_amount FROM reserve_plan_ln rp, reserve_plan_hd rph WHERE rp.contract_id = pfcc.contract_id and rph.reserve_plan_hd_id=rp.reserve_plan_hd_id AND rph.approve_status='APPROVED' and rp.reserve_plan_ln_id= (SELECT max(rp.reserve_plan_ln_id) FROM reserve_plan_ln rp, reserve_plan_hd rph WHERE rp.contract_id = pfcc.contract_id and rph.reserve_plan_hd_id=rp.reserve_plan_hd_id AND rph.approve_status='APPROVED') ),0) as received_reserve_plan_amount FROM plm_five_classify_con pfcc,plm_five_classification pfc, ( SELECT max(pfcc.five_classify_con_id) as five_classify_con_id,pfcc.contract_id FROM plm_five_classify_con pfcc,plm_five_classification pfc WHERE pfcc.five_classification_id=pfc.five_classification_id and pfc.company_id= #{request.companyId} and pfcc.contract_id NOT IN(SELECT rpl.contract_id FROM reserve_plan_hd rph, reserve_plan_ln rpl WHERE rph.reserve_plan_hd_id=rpl.reserve_plan_hd_id and rph.approve_status in ('NEW','APPROVING','APPROVED_RETURN') )
AND pfcc.change_iq = 'NORMAL'
AND pfc.status = 'APPROVED' group by pfcc.contract_id ) fcc
pfcc.five_classification_id=pfc.five_classification_id and pfc.company_id= #{request.companyId} and pfcc.five_classify_con_id=fcc.five_classify_con_id and pfcc.contract_id=fcc.contract_id and pfcc.contract_id NOT IN(SELECT rpl.contract_id FROM reserve_plan_hd rph, reserve_plan_ln rpl WHERE rph.reserve_plan_hd_id=rpl.reserve_plan_hd_id and rph.approve_status in ('NEW','APPROVING','APPROVED_RETURN') )
AND pfcc.five_classification_id = #{fiveClassificationId}
AND pfcc.change_iq = #{changeIq}
AND pfc.status = #{status}

SELECT TAB.FIVE_CLASSIFICATION_RESULT final_classification_result, nvl(SUM(TAB.remain_amount),0) remain_amount_str, nvl(SUM(TAB.remain_amount),0) remain_amount, nvl(COUNT(TAB.PROJECT_ID),0) result_count FROM ( SELECT fp.FIVE_CLASSIFICATION_RESULT, fp.PROJECT_ID, fqc.remain_amount, FC.CREATED_BY FROM FCT_PROJECT fp JOIN FCT_CONTRACT fc ON fp.project_id=fc.project_id JOIN ( SELECT cf.contract_id , SUM(cf.due_amount-nvl(cf.write_off_amount,0)) remain_amount FROM fct_quotation_cashflow cf WHERE cf.cf_item=54 GROUP BY cf.contract_id )fqc ON fqc.contract_id = fc.contract_id WHERE fp.DATA_CLASS= 'VIRTUAL_CON' AND fp.DATA_TYPE='NORMAL' AND fc.DATA_CLASS='NORMAL' AND ( fc.CONTRACT_STATUS = 'INCEPT' OR ( fc.contract_status='PENDING' AND ( SELECT COUNT(1) FROM fct_contract ft WHERE ft.data_class='CHANGE_REQ' AND ft.contract_status='INCEPT' AND ft.ref_contract_id=fc.contract_id ) >0) )
and fp.company_id = #{companyId}
UNION ALL SELECT fp.FIVE_CLASSIFICATION_RESULT, fp.PROJECT_ID, fqc.remain_amount, FC.CREATED_BY FROM PRJ_PROJECT fp JOIN CON_CONTRACT fc ON fp.project_id=fc.project_id JOIN ( SELECT cf.contract_id , SUM(cf.principal-nvl(cf.received_principal,0)) remain_amount FROM con_contract_cashflow cf WHERE cf.cf_item=1 GROUP BY cf.contract_id )fqc ON fqc.contract_id = fc.contract_id WHERE fp.DATA_CLASS= 'VIRTUAL_CON' AND fp.DATA_TYPE='NORMAL' AND fc.DATA_CLASS='NORMAL' AND ( fc.CONTRACT_STATUS = 'INCEPT' OR ( fc.contract_status='PENDING' AND ( SELECT COUNT(1) FROM fct_contract ft WHERE ft.data_class='CHANGE_REQ' AND ft.contract_status='INCEPT' AND ft.ref_contract_id=fc.contract_id ) >0) )
and fp.company_id = #{companyId}
) TAB WHERE ((SELECT COUNT(1) FROM FND_ORG_UNIT FOU JOIN FND_ORG_POSITION FOP ON FOU.UNIT_ID=FOP.UNIT_ID JOIN FND_EMPLOYEE_ASSIGNS FEA ON FEA.POSITION_ID=FOP.POSITION_ID JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FEA.EMPLOYEE_ID AND FE.ENABLED_FLAG='Y' WHERE FOU.UNIT_TYPE='SALES' AND nvl(FOU.CHIEF_POSITION_ID,0)!=FOP.POSITION_ID AND FE.EMPLOYEE_CODE = #{request.employeeCode} ) =0 OR TAB.CREATED_BY=#{request.userId}) GROUP BY TAB.FIVE_CLASSIFICATION_RESULT

mapper.update:
update plm_five_classify_con pfcc set pfcc.change_iq=#{changeIq}
where pfcc.five_classification_id = #{fiveClassificationId}
AND pfcc.change_iq = #{changeIqOld}

mapper.select:
SELECT allInfo.* FROM (SELECT cc.contract_number, cc.contract_name, cc.contract_id, cc.lease_start_date valid_from, cc.tenant_id AS bp_id, hbm.bp_name, 'CON' as contract_type, nvl(( SELECT max(ccc.times) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id GROUP BY ccc.contract_id ),0) AS all_times, ( SELECT count(*) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 9 ) AS overdue_times, nvl( ( SELECT max(ccc.fine_days) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 GROUP BY ccc.contract_id ),0) AS overdue_days, nvl( ( SELECT sum(ccc.due_amount-ccc.received_amount) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 AND ccc.overdue_status = 'Y' AND ccc.write_off_flag != 'FULL' GROUP BY ccc.contract_id),0) AS overdue_amount, nvl( ( SELECT sum(ccc.due_amount-ccc.received_amount) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 9 GROUP BY ccc.contract_id),0) AS overdue_penalty, ( SELECT CASE WHEN count(*) > 0 THEN 'N' ELSE 'Y' END FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 AND ccc.write_off_flag != 'FULL' ) AS is_settle, (select s.MEANING value_name from sys_code_value_b_v s where s.code = 'SYS.IS_SETTLE' and s.code_value =( SELECT CASE WHEN count(*) > 0 THEN 'N' ELSE 'Y' END FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 AND ccc.write_off_flag != 'FULL' ))AS is_settle_n FROM con_contract cc LEFT JOIN hls_bp_master hbm ON cc.tenant_id = hbm.bp_id WHERE cc.data_class = 'NORMAL' UNION ALL SELECT fct.contract_number, fct.contract_name, fct.contract_id, fct.valid_from, hbm.bp_id, hbm.bp_name, 'FCT' as contract_type, nvl( ( SELECT max(fqc.times) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id GROUP BY fct.contract_id ), 0 ) AS all_times, ( SELECT count(*) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item = 45 ) AS overdue_times, nvl( ( SELECT max(fqc.fine_days) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item in(54, 55, 57, 51) GROUP BY fqc.contract_id ), 0 ) AS overdue_days, nvl( ( SELECT sum(fqc.due_amount-nvl(fqc.received_amount,0)) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item IN (54, 55, 57,51) AND fqc.write_off_flag != 'FULL' GROUP BY fqc.contract_id ), 0 ) AS overdue_amount, nvl( ( SELECT sum(fqc.due_amount-nvl(fqc.received_amount,0)) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item = 45 GROUP BY fqc.contract_id ), 0 ) AS overdue_penalty, ( SELECT CASE WHEN count(*) > 0 THEN 'N' ELSE 'Y' END FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item IN (54, 55, 57,51) AND fqc.write_off_flag != 'FULL' ) AS is_settle, (select s.MEANING value_name from sys_code_value_b_v s where s.code = 'SYS.IS_SETTLE' and s.code_value =( SELECT CASE WHEN count(*) > 0 THEN 'N' ELSE 'Y' END FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item IN (54, 55, 57,51) AND fqc.write_off_flag != 'FULL')) AS is_settle_n
FROM fct_contract fct, fct_project_bp fpb, hls_bp_master hbm WHERE fct.data_class = 'NORMAL' AND fct.project_id = fpb.project_id AND fpb.bp_id = hbm.bp_id and fpb.credit_grantor_party='Y' ) allInfo
allInfo.overdue_times>0
AND (allInfo.bp_name LIKE concat(concat('%',#{contractNumber}),'%') or allInfo.contract_number LIKE concat(concat('%',#{contractNumber}),'%'))
AND allInfo.overdue_days >= #{fineDaysFrom}
AND allInfo.overdue_days <= #{fineDaysTo}
AND allInfo.is_settle = #{isSettleArray}

SELECT nvl(sum(allInfo.overdue_amount),0) as all_overdue_amount FROM ( SELECT ( SELECT count(*) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 9 ) AS overdue_times, nvl( ( SELECT sum(ccc.due_amount) - sum(ccc.received_amount) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 AND ccc.overdue_status = 'Y' AND ccc.write_off_flag != 'FULL' GROUP BY ccc.contract_id ), 0 ) AS overdue_amount FROM con_contract cc WHERE cc.data_class = 'NORMAL'
AND cc.company_id = #{companyId}
and ( ( cc.contract_status = 'INCEPT' ) OR ( cc.contract_status = 'PENDING' AND ( SELECT count(0) FROM con_contract ccc WHERE ccc.ref_contract_id = cc.contract_id AND ccc.contract_status = 'INCEPT' AND ccc.data_class = 'CHANGE_REQ' ) > 0 ) ) UNION all SELECT ( SELECT count(*) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.cf_item = 45 ) AS overdue_times, nvl( ( SELECT sum(fqc.due_amount) - sum(fqc.received_amount) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.cf_item IN (54, 55, 59) AND fqc.write_off_flag != 'FULL' GROUP BY fqc.contract_id ), 0 ) AS overdue_amount FROM fct_contract fc WHERE fc.data_class = 'NORMAL'
AND fc.company_id = #{companyId}
AND ( ( fc.contract_status = 'INCEPT' ) OR ( fc.contract_status = 'PENDING' AND ( SELECT count(0) FROM fct_contract fcc WHERE fcc.ref_contract_id = fc.contract_id and fcc.contract_status='INCEPT' and fcc.data_class='CHANGE_REQ' ) > 0 ) ) ) allInfo WHERE allInfo.overdue_times > 0

SELECT nvl(sum( allContracts.all_due_amount ),0) AS all_due_amount, nvl(sum( allContracts.all_received_amount ),0) AS all_received_amount, nvl(sum( allContracts.all_overdue_amount ),0) AS all_overdue_amount FROM ( SELECT cc.contract_id, 'CON' AS contract_type, cc.contract_number, nvl(cash.all_due_amount, 0) AS all_due_amount, nvl(cash.all_received_amount, 0) AS all_received_amount, nvl(cash.all_overdue_amount, 0) AS all_overdue_amount FROM con_contract cc LEFT JOIN ( SELECT ccc.contract_id, sum(ccc.due_amount) all_due_amount, sum(ccc.received_amount) all_received_amount, sum(case when ccc.overdue_status='Y' then (ccc.due_amount-ccc.received_amount) else 0 end) all_overdue_amount FROM con_contract_cashflow ccc WHERE ccc.cf_item = 1 GROUP BY ccc.contract_id ) cash ON cc.contract_id = cash.contract_id WHERE cc.data_class = 'NORMAL'
AND cc.company_id = #{companyId}
and ( ( cc.contract_status = 'INCEPT' ) OR ( cc.contract_status = 'PENDING' AND ( SELECT count(0) FROM con_contract ccc WHERE ccc.ref_contract_id = cc.contract_id AND ccc.contract_status = 'INCEPT' AND ccc.data_class = 'CHANGE_REQ' ) > 0 ) )
UNION SELECT fc.contract_id AS contract_id, 'FCT' AS contract_type, fc.contract_number, nvl(cash.all_due_amount, 0) AS all_due_amount, nvl(cash.all_received_amount, 0) AS all_received_amount, nvl(cash.all_overdue_amount, 0) AS all_overdue_amount FROM fct_contract fc LEFT JOIN ( SELECT fqc.contract_id, SUM(fqc.due_amount) all_due_amount, SUM(fqc.received_amount) all_received_amount, sum(case when fqc.overdue_status='Y' then (fqc.due_amount-fqc.received_amount) else 0 end) all_overdue_amount FROM fct_quotation_cashflow fqc WHERE fqc.cf_item in (54,55) GROUP BY fqc.contract_id ) cash ON fc.contract_id = cash.contract_id WHERE fc.data_class = 'NORMAL'
AND fc.company_id = #{companyId}
AND ( ( fc.contract_status = 'INCEPT' ) OR ( fc.contract_status = 'PENDING' AND ( SELECT count(0) FROM fct_contract fcc WHERE fcc.ref_contract_id = fc.contract_id and fcc.contract_status='INCEPT' and fcc.data_class='CHANGE_REQ' ) > 0 ) ) ) allContracts

SELECT nvl(sum(case when allInfo.overdue_days <= 30 then allInfo.overdue_amount else 0 end ),0) AS month_overdue_amount, nvl(sum(case when allInfo.overdue_days > 30 and allInfo.overdue_days <= 90 then allInfo.overdue_amount else 0 end ),0) AS quarter_overdue_amount, nvl(sum(case when allInfo.overdue_days > 90 and allInfo.overdue_days <= 180 then allInfo.overdue_amount else 0 end ),0) AS halfYear_overdue_amount, nvl(sum(case when allInfo.overdue_days > 180 then allInfo.overdue_amount else 0 end ),0) AS halfYear_up_overdue_amount FROM ( SELECT ( SELECT count(*) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 9 ) AS overdue_times, nvl( ( SELECT sum(ccc.due_amount-ccc.received_amount) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 AND ccc.overdue_status = 'Y' AND ccc.write_off_flag != 'FULL' GROUP BY ccc.contract_id ), 0 ) AS overdue_amount, nvl( ( SELECT max(ccc.fine_days) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 1 GROUP BY ccc.contract_id ), 0 ) AS overdue_days FROM con_contract cc LEFT JOIN hls_bp_master hbm ON cc.tenant_id = hbm.bp_id WHERE cc.data_class = 'NORMAL'
AND cc.company_id = #{companyId}
UNION ALL SELECT ( SELECT count(*) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item = 45 ) AS overdue_times, nvl( ( SELECT sum(fqc.due_amount - nvl(fqc.received_amount,0)) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item IN (54, 55) AND fqc.overdue_status = 'Y' AND fqc.write_off_flag != 'FULL' GROUP BY fqc.contract_id ),0 ) AS overdue_amount, nvl( ( SELECT max(fqc.fine_days) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fct.contract_id AND fqc.cf_item IN (54, 55) GROUP BY fct.contract_id ), 0 ) AS overdue_days FROM fct_contract fct WHERE fct.data_class = 'NORMAL'
AND fct.company_id = #{companyId}
) allInfo
allInfo.overdue_times > 0

SELECT distinct sua.user_id from fnd_employee_assigns fea,fnd_org_position fop,sys_user_allocation sua
WHERE fea.position_id = fop.position_id
AND fea.employee_assign_id = sua.employee_assign_id
AND fop.position_code = #{positionCode}
AND fea.company_id = #{companyId}
AND sua.COMPANY_ID = #{companyId}

SELECT ccc.contract_id, ccc.cashflow_id, ccc.times, ccc.cf_item, ccc.due_amount due_amount, ccc.due_date due_date_str, ccc.received_amount received_amount, ccc.write_off_flag, ccc.full_write_off_date last_received_date_str, ccc.interest interest, ccc.received_interest received_interest, ccc.principal principal, (ccc.received_principal received_principal, (CASE WHEN cf.cashflow_id IS NULL THEN NULL ELSE ccc.due_amount- nvl(ccc.received_amount,0) END) overdue_amount, cf.due_amount overdue_fine_amount, hci.description AS cf_item_desc FROM con_contract_cashflow ccc JOIN con_contract cc ON ccc.contract_id = cc.contract_id LEFT JOIN hls_cashflow_item hci ON ccc.cf_item = hci.cf_item LEFT JOIN con_contract_cashflow cf ON cf.contract_id = cc.contract_id AND cf.cf_item=9 AND cf.generated_source='DAYEND' AND cf.generated_source_doc_id=ccc.cashflow_id WHERE ccc.cf_item != 9 AND ccc.due_date<=sysdate
AND cc.contract_id = #{contractId}
ORDER BY ccc.times

SELECT DISTINCT CON.EMPLOYEE_ASSIGN_ID FROM ( SELECT PEA.EMPLOYEE_ASSIGN_ID FROM PRJ_PROJECT P JOIN FND_EMPLOYEE_ASSIGNS PEA ON P.EMPLOYEE_ID=PEA.EMPLOYEE_ID WHERE P.DATA_CLASS = 'VIRTUAL_CON' AND P.DATA_TYPE = 'NORMAL' AND P.TENANT_ID=#{bpId}
UNION SELECT FP.EMPLOYEE_ASSIGN_ID FROM FCT_PROJECT FP JOIN FCT_PROJECT_BP FPB ON FP.PROJECT_ID = FPB.PROJECT_ID WHERE FP.DATA_TYPE = 'NORMAL' AND FP.DATA_CLASS = 'VIRTUAL_CON' AND FPB.CREDIT_GRANTOR_PARTY = 'Y' AND FPB.BP_ID=#{bpId}
) CON
